CREATE DATABASE IF NOT EXISTS homeo_tabeeb CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE homeo_tabeeb;

CREATE TABLE users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,phone VARCHAR(60),password_hash VARCHAR(255) NOT NULL,role ENUM('super_admin','admin','manager','doctor') NOT NULL DEFAULT 'doctor',status ENUM('active','inactive') NOT NULL DEFAULT 'active',created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NULL ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE patients (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,case_code VARCHAR(40) NOT NULL UNIQUE,full_name VARCHAR(160) NOT NULL,age INT NOT NULL,gender VARCHAR(30) NOT NULL,phone VARCHAR(60) NOT NULL,whatsapp VARCHAR(60) NOT NULL,email VARCHAR(190),city VARCHAR(120) NOT NULL,address TEXT NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX idx_phone (phone),INDEX idx_whatsapp (whatsapp)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE patient_cases (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,patient_id BIGINT UNSIGNED NOT NULL,case_code VARCHAR(40) NOT NULL UNIQUE,chief_complaint TEXT NOT NULL,full_form_json JSON NOT NULL,status VARCHAR(60) NOT NULL DEFAULT 'chat_started',emergency_flag TINYINT(1) NOT NULL DEFAULT 0,ai_status VARCHAR(60) NOT NULL DEFAULT 'pending',doctor_status VARCHAR(60) NOT NULL DEFAULT 'pending',order_status VARCHAR(60) NOT NULL DEFAULT 'none',created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NULL ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY (patient_id) REFERENCES patients(id),INDEX idx_status (status),INDEX idx_doctor_status (doctor_status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE chat_messages (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,case_id BIGINT UNSIGNED NOT NULL,sender_type ENUM('patient','ai','system','doctor','admin') NOT NULL,message MEDIUMTEXT NOT NULL,metadata_json JSON NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY (case_id) REFERENCES patient_cases(id),INDEX idx_case_created (case_id,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE ai_case_reports (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,case_id BIGINT UNSIGNED NOT NULL,diagnosis_summary MEDIUMTEXT,probable_conditions_json JSON,selected_rubrics_json JSON,matched_remedies_json JSON,matched_formulas_json JSON,confidence_score INT DEFAULT 0,safety_flags_json JSON,source_references_json JSON,raw_ai_response_json JSON,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY (case_id) REFERENCES patient_cases(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE doctor_reviews (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,case_id BIGINT UNSIGNED NOT NULL,doctor_id BIGINT UNSIGNED NOT NULL,review_status ENUM('approved','edited','rejected') NOT NULL,doctor_notes TEXT,changes_json JSON,approved_at DATETIME NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY (case_id) REFERENCES patient_cases(id),FOREIGN KEY (doctor_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE prescriptions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,case_id BIGINT UNSIGNED NOT NULL,doctor_id BIGINT UNSIGNED NOT NULL,prescription_code VARCHAR(40) NOT NULL UNIQUE,diagnosis_text MEDIUMTEXT NOT NULL,instructions MEDIUMTEXT,warning_notes TEXT,verified_text VARCHAR(190) NOT NULL,status VARCHAR(40) NOT NULL DEFAULT 'approved',created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY (case_id) REFERENCES patient_cases(id),FOREIGN KEY (doctor_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE prescription_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,prescription_id BIGINT UNSIGNED NOT NULL,item_type ENUM('remedy','formula') NOT NULL,medicine_name VARCHAR(190),formula_name VARCHAR(190),potency VARCHAR(80),dose VARCHAR(120),frequency VARCHAR(120),duration VARCHAR(120),instructions TEXT,source_reference TEXT,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY (prescription_id) REFERENCES prescriptions(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE vendors (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(160) NOT NULL,phone VARCHAR(60),whatsapp VARCHAR(60),address TEXT,status ENUM('active','inactive') NOT NULL DEFAULT 'active',created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE orders (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,case_id BIGINT UNSIGNED NOT NULL,prescription_id BIGINT UNSIGNED NULL,patient_id BIGINT UNSIGNED NOT NULL,order_code VARCHAR(40) NOT NULL UNIQUE,delivery_name VARCHAR(160) NOT NULL,delivery_phone VARCHAR(60) NOT NULL,delivery_whatsapp VARCHAR(60) NOT NULL,delivery_address TEXT NOT NULL,city VARCHAR(120) NOT NULL,payment_method VARCHAR(80) NOT NULL DEFAULT 'Cash on Delivery',vendor_id BIGINT UNSIGNED NULL,status ENUM('requested','pending_doctor_verification','approved','contacted','sent_to_vendor','out_for_delivery','delivered','cancelled','rejected') NOT NULL DEFAULT 'requested',admin_notes TEXT,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NULL ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY (case_id) REFERENCES patient_cases(id),FOREIGN KEY (prescription_id) REFERENCES prescriptions(id),FOREIGN KEY (patient_id) REFERENCES patients(id),FOREIGN KEY (vendor_id) REFERENCES vendors(id),INDEX idx_order_status (status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE order_status_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id BIGINT UNSIGNED NOT NULL,status VARCHAR(60) NOT NULL,note TEXT,changed_by BIGINT UNSIGNED NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY (order_id) REFERENCES orders(id) ON DELETE CASCADE,FOREIGN KEY (changed_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE knowledge_sources (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,source_key VARCHAR(120) NOT NULL UNIQUE,source_name VARCHAR(190) NOT NULL,author VARCHAR(190),source_type VARCHAR(80),url TEXT,notes TEXT,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE remedies (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,remedy_key VARCHAR(120) NOT NULL UNIQUE,remedy_name VARCHAR(190) NOT NULL,normalized_name VARCHAR(190),source_id BIGINT UNSIGNED NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY (source_id) REFERENCES knowledge_sources(id),INDEX idx_remedy_name (remedy_name)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE remedy_aliases (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,remedy_id BIGINT UNSIGNED NOT NULL,alias_name VARCHAR(190) NOT NULL,language VARCHAR(40),created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY (remedy_id) REFERENCES remedies(id),INDEX idx_alias (alias_name)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE symptoms_rubrics (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,rubric_key VARCHAR(190) NOT NULL UNIQUE,rubric_text TEXT NOT NULL,parent_id BIGINT UNSIGNED NULL,category VARCHAR(120),source_id BIGINT UNSIGNED NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY (parent_id) REFERENCES symptoms_rubrics(id),FOREIGN KEY (source_id) REFERENCES knowledge_sources(id),FULLTEXT KEY ft_rubric_text (rubric_text)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE remedy_symptom_relations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,remedy_id BIGINT UNSIGNED NOT NULL,rubric_id BIGINT UNSIGNED NOT NULL,grade INT DEFAULT 1,source_id BIGINT UNSIGNED NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY (remedy_id) REFERENCES remedies(id),FOREIGN KEY (rubric_id) REFERENCES symptoms_rubrics(id),FOREIGN KEY (source_id) REFERENCES knowledge_sources(id),UNIQUE KEY uniq_rel (remedy_id,rubric_id,source_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE materia_medica_pages (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,source_id BIGINT UNSIGNED NULL,book_slug VARCHAR(120),remedy_name VARCHAR(190),title VARCHAR(255),full_text MEDIUMTEXT,url TEXT,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY (source_id) REFERENCES knowledge_sources(id),FULLTEXT KEY ft_mm_text (full_text)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE extra_documents (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,source_key VARCHAR(120),title VARCHAR(255),author VARCHAR(190),text MEDIUMTEXT,metadata_json JSON,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE extra_sections (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,document_id BIGINT UNSIGNED NULL,section_title VARCHAR(255),section_text MEDIUMTEXT,section_type VARCHAR(80),source_key VARCHAR(120),created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY (document_id) REFERENCES extra_documents(id),FULLTEXT KEY ft_extra_section_text (section_text)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE formula_candidates (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,source_key VARCHAR(120),formula_name VARCHAR(190),condition_text TEXT,formula_text MEDIUMTEXT,extracted_medicines_json JSON,dose_text TEXT,confidence DECIMAL(5,2) DEFAULT 0,review_status VARCHAR(40) DEFAULT 'pending',created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FULLTEXT KEY ft_formula_text (formula_text)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE approved_formulas (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,formula_name VARCHAR(190) NOT NULL,condition_text TEXT,medicines_json JSON,potency_text TEXT,dose_text TEXT,doctor_id BIGINT UNSIGNED NULL,source_reference TEXT,status VARCHAR(40) NOT NULL DEFAULT 'active',created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY (doctor_id) REFERENCES users(id),FULLTEXT KEY ft_approved_condition (condition_text),FULLTEXT KEY ft_approved_name (formula_name)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE ai_corrections (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,case_id BIGINT UNSIGNED NULL,doctor_id BIGINT UNSIGNED NOT NULL,correction_type VARCHAR(80),original_ai_value MEDIUMTEXT,corrected_value MEDIUMTEXT,reason TEXT,approved_for_learning TINYINT(1) NOT NULL DEFAULT 0,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY (case_id) REFERENCES patient_cases(id),FOREIGN KEY (doctor_id) REFERENCES users(id),FULLTEXT KEY ft_correction_value (corrected_value)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE safety_rules (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,rule_key VARCHAR(120) NOT NULL UNIQUE,trigger_keywords TEXT NOT NULL,severity ENUM('warning','urgent','emergency') NOT NULL DEFAULT 'emergency',instruction TEXT NOT NULL,status ENUM('active','inactive') NOT NULL DEFAULT 'active',created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE api_usage_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,case_id BIGINT UNSIGNED NULL,model VARCHAR(190),tokens_input INT DEFAULT 0,tokens_output INT DEFAULT 0,cost_estimate DECIMAL(10,5) DEFAULT 0,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY (case_id) REFERENCES patient_cases(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE activity_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NULL,action VARCHAR(120) NOT NULL,details_json JSON,ip_address VARCHAR(60),created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY (user_id) REFERENCES users(id),INDEX idx_action_created (action,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE system_settings (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,setting_key VARCHAR(120) NOT NULL UNIQUE,setting_value TEXT,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NULL ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
